// Electrotherapy topics for Dr. MGR BPT Electrotherapy I and II papers. Written in Learn Anywhere's own words.
window.LIB_EXTRA = (window.LIB_EXTRA || []).concat([
{
  id:"swd", title:"Short wave diathermy (continuous and pulsed)", subject:"Electrotherapy", region:"Deep tissues", stages:"steps",
  aliases:["SWD","short wave diathermy","PSWD","pulsed shortwave","condenser field","cable method","deep heating"],
  simple:"Short wave diathermy passes a high-frequency electromagnetic field through the body to heat deeper tissues such as joints and muscles. In continuous mode it heats; in pulsed mode the heat is carried away between pulses, so the effect is mostly non-thermal. It needs careful screening because metal and some conditions make it dangerous.",
  flow:["Machine produces 27.12 MHz oscillating current","Condenser plates or inductive cable create a field","Tissue ions and dipoles oscillate and produce heat","Patient feels mild comfortable warmth (continuous mode)","Pulsed mode gives short bursts with low mean power","Deep heat reduces pain, spasm and stiffness"],
  exam:[
    {h:"Definition", p:["Therapeutic use of a high-frequency alternating current (27.12 MHz, wavelength about 11 m) to produce heat in the deeper tissues.","Two modes: continuous SWD (thermal) and pulsed SWD (mainly athermal at low mean power)."]},
    {h:"Physics and production", p:["Machine circuit: power supply, oscillator (resonator) circuit and patient circuit, which must be tuned into resonance with the oscillator.","Capacitor (condenser) field method: patient tissue acts as the dielectric between two plates; fat and superficial tissue heat most.","Inductive (cable or drum) method: eddy currents in the tissue; heats tissues with good conductivity such as muscle and blood-rich structures.","Electrode spacing: wider spacing gives more even, deeper heating; placement can be contraplanar, coplanar or longitudinal."]},
    {h:"Physiological effects", p:["Rise in tissue temperature, increased metabolism, vasodilation and increased blood flow.","Reduced pain (sensory nerve effect), reduced muscle spasm and increased extensibility of collagen before stretching.","Pulsed SWD is claimed to aid oedema resolution and tissue healing; the evidence for this is weak."]},
    {h:"Dosage and parameters", p:["Continuous SWD: subjective dosage, mild to comfortable warmth (Schliephake doses I sub-thermal to IV vigorous). Time 20-30 minutes for chronic conditions, daily or alternate days.","Acute conditions: low or no perceptible heat, shorter time (about 10-15 minutes).","Pulsed SWD: pulse duration about 65-400 microseconds, pulse repetition 26-400 Hz (up to 800 Hz on some units), high peak power with low mean power; 15-20 minutes.","Prepare the patient: remove all metal, dry skin, towelling between skin and electrode, test thermal sensation, explain warmth only."]},
    {h:"Indications", p:["Chronic osteoarthritis of the knee, chronic low back pain, sinusitis (historical use), chronic inflammatory pelvic conditions, muscle spasm, before stretching or exercise."]},
    {h:"Dangers and contraindications", p:["Dangers: burns (concentrated field, sweat, metal), electric shock, overdose, faintness, scald from moist towel, interference with nearby equipment.","Contraindications: metal implants or jewellery in the field, cardiac pacemaker (no SWD in the room), pregnancy, malignancy, haemorrhage, active TB, DVT, ischaemic tissue, impaired sensation, unreliable patient, eyes, testes, growing epiphyses, recent radiotherapy, febrile patient.","Therapist safety: keep at least 1 m from continuous SWD leads; pregnant therapists should avoid the field."]},
    {h:"Conclusion", p:["SWD is a convenient deep heating agent, but strict safety screening is essential and it should be an adjunct to exercise, since evidence for added benefit is limited."]}
  ],
  tip:"Draw the machine as three boxes (power supply, oscillator circuit, patient circuit) with the tuning link. Below it draw the condenser method: two plates, spacing, and the field lines through a knee, labelled contraplanar.",
  evidence:[["Continuous or pulsed SWD for knee OA","Small, inconsistent effect on pain; may add little to exercise","Low"],["Pulsed SWD for soft tissue healing","Laboratory effects, weak clinical evidence","Very low"],["SWD for chronic low back pain","No clear benefit over exercise alone","Low"]],
  evidenceSource:"Systematic review of SWD in knee OA (Laufer and Dar, Osteoarthritis Cartilage 2012) and Cameron, Physical Agents in Rehabilitation",
  outcomes:[["NPRS or VAS","Pain intensity"],["WOMAC","Knee OA pain, stiffness and function"],["Goniometry","Range gained after heating and stretching"]],
  recent:["Use of continuous SWD has fallen in many clinics because of safety concerns and weak evidence, with exercise-first care preferred for OA and back pain."],
  mnemonic:{word:"HEAT", items:[["H","Hardware off: remove all metal"],["E","Exam sensation with hot and cold test tubes"],["A","Air gap or towelling between electrode and skin"],["T","Tune to resonance and time 20-30 min"]], extra:"Patient must report any increase in warmth beyond mild comfort."},
  example:"A 60-year-old woman with chronic knee OA in Madurai gets condenser-field SWD for 20 minutes before quadriceps strengthening. She has no metal implants and normal thermal sensation.",
  flags:["Cardiac pacemaker or implanted stimulator (patient and anyone nearby)","Metal implants or jewellery in the field: risk of deep burn","Impaired thermal sensation or confused patient","Pregnancy, malignancy, haemorrhage or active infection in the area"],
  viva:[["What frequency is used in SWD?","27.12 MHz, wavelength about 11 metres."],["Which method heats fat more?","The condenser (capacitor) field method; the inductive cable method heats muscle and well-perfused tissues more."],["Why is the circuit tuned?","The patient circuit must be in resonance with the oscillator circuit so maximum energy is transferred to the patient."]],
  refs:[{b:"cameron",ch:"Diathermy"},{b:"prentice",ch:"Shortwave and microwave diathermy"},{c:"Laufer Y, Dar G. Effectiveness of thermal and athermal short-wave diathermy for the management of knee osteoarthritis: a systematic review and meta-analysis. Osteoarthritis Cartilage. 2012;20:957-966.", q:"Laufer Dar short-wave diathermy knee osteoarthritis meta-analysis"}],
  keywords:"short wave diathermy SWD pulsed condenser inductive 27.12 MHz",
  mcq:[["The frequency of short wave diathermy used in physiotherapy is:",["2.45 GHz","27.12 MHz","1 MHz","50 Hz"],1,"27.12 MHz is the standard SWD frequency; 2.45 GHz is microwave and 1 MHz is ultrasound."],["Which is an absolute contraindication to SWD?",["Chronic knee OA","Cardiac pacemaker","Muscle spasm","Chronic low back pain"],1,"The field can interfere with pacemaker function."]]
},
{
  id:"faradic", title:"Faradic and surged faradic current (muscle re-education)", subject:"Electrotherapy", region:"Innervated muscle", stages:"steps",
  aliases:["faradic current","surged faradism","NMES","muscle re-education","faradic foot bath","quadriceps inhibition"],
  simple:"Faradic current is a short-duration pulsed current that stimulates motor nerves and makes an innervated muscle contract. Surging it on and off gives a contraction followed by rest, close to a normal voluntary contraction. It helps patients learn to contract a muscle again after pain, surgery or disuse.",
  flow:["Short pulses 0.1-1 ms at 50-100 Hz","Pulses depolarise the motor nerve, not muscle fibres","Fused tetanic contraction of an innervated muscle","Surging gives a gradual rise, hold and rest","Patient joins in voluntarily with each surge","Voluntary control returns; current is weaned off"],
  exam:[
    {h:"Definition", p:["A short-duration interrupted current, classically an asymmetric alternating current from an induction coil, with pulse duration about 0.1-1 ms and frequency about 50-100 Hz.","Modern stimulators use rectangular or biphasic 'faradic-type' pulses with the same parameters."]},
    {h:"Physiological effects", p:["Stimulates sensory nerves (prickling) and motor nerves, producing a tetanic contraction of innervated muscle.","Does not stimulate denervated muscle because the pulses are too short.","Muscle pumping improves venous and lymphatic return; repeated contraction maintains muscle properties and teaches the movement."]},
    {h:"Surging and dosage", p:["Surged faradism: current rises gradually, holds and falls, followed by a rest; surge 1-2 s on with rest 2-6 s initially (about 1:3), reducing rest as fatigue allows.","Intensity: enough for a strong comfortable contraction; adjust per motor point.","Number: about 3 sets of 10-30 contractions with rests between sets, daily; stop when fatigue appears.","Motor point method (small active electrode on the motor point) or group method (one electrode on each end of a muscle group)."]},
    {h:"Indications", p:["Muscle inhibition after surgery or injury (quadriceps after knee surgery or effusion).","Re-education of a new action after tendon transfer.","Weak intrinsic foot muscles in flat foot (faradic foot bath), pelvic floor weakness.","Venous and lymphatic return (faradism under pressure for oedema)."]},
    {h:"Contraindications and dangers", p:["Cardiac pacemaker, over the anterior neck (carotid sinus), over the pregnant uterus, active DVT, malignancy in the area, broken skin, impaired sensation, epilepsy (caution).","Dangers: electrical burns from poor electrode contact, shock, muscle fatigue or overstrain."]},
    {h:"Conclusion", p:["Surged faradism is a re-education tool for innervated muscle; it must always be combined with active exercise and withdrawn as voluntary control returns."]}
  ],
  tip:"Draw the waveform: a train of short peaks rising in height, a plateau, falling, then a flat rest period; label surge, rest, pulse duration 1 ms and frequency 50 Hz. Add a leg with electrodes on the quadriceps motor point.",
  evidence:[["NMES added to exercise after total knee arthroplasty","Better early quadriceps strength and function","Moderate"],["NMES for quadriceps after ACL reconstruction","Small strength gains when combined with exercise","Low-moderate"],["Faradic foot bath for flat foot","Long-standing clinical use, little trial evidence","Very low"]],
  evidenceSource:"Stevens-Lapsley et al., Phys Ther 2012, and Cameron, Physical Agents in Rehabilitation",
  outcomes:[["Oxford MRC muscle grade","Strength of the stimulated muscle"],["Extensor lag","Quadriceps control after knee surgery"],["Hand-held dynamometry","Measured force"]],
  recent:["Stevens-Lapsley et al. (Phys Ther 2012) showed early quadriceps NMES after total knee arthroplasty improved strength and function compared with exercise alone."],
  mnemonic:{word:"SURGE", items:[["S","Short pulses 0.1-1 ms"],["U","Used only on innervated muscle"],["R","Rest 2-6 s between surges"],["G","Gradual rise and fall"],["E","Exercise actively with every surge"]], extra:"Frequency 50-100 Hz gives a fused tetanic contraction."},
  example:"A 25-year-old footballer in Chennai cannot do a straight leg raise 3 days after arthroscopy. Surged faradism to the quadriceps motor point while he tries to set the quadriceps restores the contraction in a week.",
  flags:["Cardiac pacemaker or implanted defibrillator","Electrodes over the carotid sinus or across the chest","Pregnant uterus, DVT, malignancy in the treatment area","Broken skin or absent sensation under electrodes"],
  viva:[["Why is faradic current not used for denervated muscle?","Its pulses (under 1 ms) are too short to excite denervated muscle fibres, which need long pulses of about 100 ms or more."],["What is the purpose of surging?","To give a contraction followed by relaxation, imitating a voluntary contraction and preventing fatigue."],["What is a motor point?","The point on the skin where the motor nerve enters the muscle, giving a contraction with the least current."]],
  refs:[{b:"cameron",ch:"Electrical currents for muscle contraction"},{b:"prentice",ch:"Basic principles of electricity and electrical stimulating currents"},{c:"Stevens-Lapsley JE, Balter JE, Wolfe P, Eckhoff DG, Kohrt WM. Early neuromuscular electrical stimulation to improve quadriceps muscle strength after total knee arthroplasty: a randomized controlled trial. Phys Ther. 2012;92:210-226.", q:"Stevens-Lapsley early neuromuscular electrical stimulation quadriceps total knee arthroplasty"}],
  keywords:"faradic current surged faradism muscle re-education NMES motor point",
  mcq:[["The pulse duration of faradic current is about:",["100 ms","0.1-1 ms","300 ms","10 s"],1,"Faradic pulses are short, 0.1-1 ms, enough to excite motor nerves."],["Surged faradism is mainly used for:",["Denervated muscle","Muscle re-education of innervated muscle","Wound healing","Hyperhidrosis"],1,"It produces contraction and rest in innervated muscle to retrain voluntary control."]]
},
{
  id:"galvanic-ids", title:"Interrupted galvanic (direct) current for denervated muscle", subject:"Electrotherapy", region:"Denervated muscle", stages:"steps",
  aliases:["IDC","interrupted direct current","galvanic current","denervated muscle stimulation","long pulse stimulation","Bell's palsy","foot drop"],
  simple:"When a muscle loses its nerve supply, short pulses no longer make it contract. Long-duration pulses of direct current, switched on and off, can still make the muscle fibres contract. It is used to try to slow wasting while the nerve regrows, though the evidence is mixed.",
  flow:["Nerve injury leads to denervation of muscle","Muscle no longer responds to short faradic pulses","Long pulses (about 100 ms or more) applied","Muscle fibres contract slowly and sluggishly","Repeated contractions may slow atrophy and fibrosis","Stopped once voluntary contraction returns"],
  exam:[
    {h:"Definition", p:["A unidirectional current interrupted into long pulses (about 100-300 ms or longer) separated by rest intervals, used to stimulate denervated muscle directly."]},
    {h:"Types of pulse", p:["Rectangular pulses: instant rise, stimulate both innervated and denervated muscle.","Trapezoidal, triangular or saw-tooth pulses: slow rise; normal innervated muscle accommodates to the slow rise, so denervated muscle can be stimulated selectively without discomfort from normal neighbours.","Rest interval about 2-3 s (roughly 20-30 pulses per minute) because denervated muscle fatigues quickly."]},
    {h:"Physiological effects and rationale", p:["Denervated muscle fibres have a high threshold and long chronaxie, so they need long pulses.","The aim is to keep the muscle healthier (reduce atrophy, fibrosis and oedema) until reinnervation, and to maintain the patient's awareness of the movement.","Galvanic current also produces chemical changes under electrodes: acid under the anode, alkali under the cathode."]},
    {h:"Technique and dosage", p:["Test sensation, clean and moisten skin with saline or water pads.","Active electrode (usually cathode) over the muscle belly, indifferent electrode proximally; denervated muscle has no motor point, so use the belly or the stable/labile technique.","Intensity enough for a visible, slow contraction; about 3 sets of 10-30 contractions, once or several times a day, avoiding fatigue.","Common uses: Bell's palsy (facial muscles), radial or common peroneal nerve palsy, brachial plexus injury."]},
    {h:"Dangers and contraindications", p:["Chemical burns under electrodes, the main danger of galvanic current; avoid high current density and use thick wet pads.","Electric shock, skin irritation; general contraindications as for electrical stimulation (pacemaker, malignancy, DVT, broken skin, impaired sensation).","In Bell's palsy, many clinicians avoid stimulation in the acute stage, as it may encourage synkinesis; the evidence is limited."]},
    {h:"Conclusion", p:["IDC is the classic method for stimulating denervated muscle, but human evidence that it speeds recovery is inconsistent, so it is an adjunct to splinting, positioning and re-education."]}
  ],
  tip:"Draw two waveforms side by side: a rectangular pulse (100 ms on, 2-3 s off) and a triangular slow-rise pulse, labelled 'innervated muscle accommodates'. Add electrodes over the tibialis anterior belly for foot drop.",
  evidence:[["Long-pulse stimulation of denervated muscle (animal studies)","Slows atrophy in some studies","Low"],["Electrical stimulation in Bell's palsy","Insufficient evidence of benefit","Very low"],["Home-based long-pulse stimulation in long-term denervated SCI muscle","Muscle mass recovery in small trials","Low"]],
  evidenceSource:"Cameron, Physical Agents in Rehabilitation, and the European RISE project reports (Kern et al.)",
  outcomes:[["Strength-duration curve","Tracks reinnervation"],["MRC grade","Voluntary strength returning"],["House-Brackmann grade","Facial nerve recovery in Bell's palsy"]],
  recent:["The European RISE project (Kern and colleagues) used home-based long-pulse stimulation to rebuild muscle in long-term denervated legs after spinal cord injury."],
  mnemonic:{word:"LONG", items:[["L","Long pulses, 100 ms or more"],["O","Off time 2-3 s between pulses"],["N","No response to faradic: it is denervated"],["G","Galvanic burns: watch the skin"]], extra:"Triangular pulses stimulate denervated muscle selectively."},
  example:"A 30-year-old man in Coimbatore has a common peroneal nerve palsy after a fibular neck fracture. Tibialis anterior shows no response to faradic current, so triangular long-pulse stimulation is given with an ankle-foot orthosis while recovery is awaited.",
  flags:["Chemical burns under electrodes, especially the cathode","Impaired sensation over the denervated area","Pacemaker, broken skin, malignancy or DVT in the area"],
  viva:[["Why do we use triangular pulses for denervated muscle?","Innervated muscle accommodates to a slowly rising current, so only the denervated muscle contracts."],["What is the typical pulse duration for IDC?","About 100 ms or longer, with 2-3 s rest."],["What happens under the cathode in galvanic current?","An alkali (sodium hydroxide) forms, which can cause a chemical burn."]],
  refs:[{b:"cameron",ch:"Electrical currents for muscle contraction"},{b:"prentice",ch:"Basic principles of electricity and electrical stimulating currents"},{c:"Kern H, et al. Home-based functional electrical stimulation rescues permanently denervated muscles in paraplegic patients with complete lower motor neuron lesion. Neurorehabil Neural Repair. 2010;24:709-721.", q:"Kern home-based functional electrical stimulation denervated muscles paraplegic"}],
  keywords:"interrupted direct current galvanic denervated muscle triangular pulse",
  mcq:[["Selective stimulation of denervated muscle uses which pulse shape?",["Rectangular","Triangular (slow rise)","Faradic","Sinusoidal 50 Hz"],1,"Innervated muscle accommodates to slow rise, so only denervated muscle responds."],["The main danger of galvanic current is:",["Deep heat burn","Chemical burn under electrodes","Eye injury","Photosensitivity"],1,"Electrolysis under the electrodes produces acid and alkali."]]
},
{
  id:"sd-curve", title:"Strength-duration curve, rheobase and chronaxie (electrodiagnosis)", subject:"Electrotherapy", region:"Peripheral nerve", stages:"steps",
  aliases:["SD curve","strength duration curve","rheobase","chronaxie","electrodiagnosis","denervation","reaction of degeneration"],
  simple:"A strength-duration curve shows how much current is needed to make a muscle just contract at different pulse lengths. A normally innervated muscle needs little current even at short pulses, while a denervated one needs long pulses. Plotting it helps tell whether a nerve is damaged and whether it is recovering.",
  flow:["Choose pulse durations from 300 ms down to 0.01 ms","Find minimal contraction intensity at each duration","Plot intensity (y) against pulse duration (x)","Read rheobase and chronaxie from the curve","Shape shows normal, partial or complete denervation","Repeat every 2-3 weeks to track reinnervation"],
  exam:[
    {h:"Definition", p:["A graph of the minimum stimulus intensity needed for a just-visible contraction against pulse duration, used to assess the nerve supply of a muscle."]},
    {h:"Key terms", p:["Rheobase: the minimum intensity of a long-duration pulse (about 100-300 ms) that produces a minimal contraction.","Chronaxie: the pulse duration needed to produce a minimal contraction at twice the rheobase intensity. Normal is under 1 ms (often about 0.1 ms); denervated muscle is much longer (often over 10 ms).","Utilisation time: the pulse duration at rheobase beyond which longer pulses do not lower the threshold."]},
    {h:"Procedure", p:["Explain, test sensation, patient relaxed and warm.","Constant-current (or constant-voltage) stimulator with rectangular pulses; indifferent electrode proximally, active electrode on the motor point (or belly if denervated).","Start with 300 ms and reduce stepwise (300, 100, 30, 10, 3, 1, 0.3, 0.1, 0.03, 0.01 ms), recording the intensity for a minimal contraction each time.","Plot on log graph paper. Perform after at least 10-14 days of injury, because the distal nerve stays excitable until Wallerian degeneration is complete."]},
    {h:"Interpretation", p:["Normal innervation: curve flat to the left and rises only at very short durations; chronaxie under 1 ms.","Complete denervation: curve shifted up and to the right, no response at short pulses; long chronaxie.","Partial denervation: a kink (discontinuity) where innervated and denervated fibres respond at different durations.","Reinnervation: on serial tests the curve moves left and down and the kink shifts."]},
    {h:"Advantages and limitations", p:["Cheap, simple, non-invasive and repeatable by physiotherapists.","Does not localise the lesion, is less sensitive than nerve conduction studies and EMG, and depends on patient cooperation and skin factors."]},
    {h:"Conclusion", p:["The SD curve is a simple bedside electrodiagnostic test showing the state of muscle innervation; NCS and EMG are now preferred for detailed diagnosis."]}
  ],
  tip:"Draw log pulse duration on the x-axis (0.01 to 300 ms) and intensity on y. Draw a normal curve low and to the left and a denervated one up and to the right; mark rheobase, 2 x rheobase and chronaxie with dotted lines, and add a kinked curve for partial denervation.",
  evidence:[["SD curve for detecting denervation","Useful screening, less sensitive than EMG","Low-moderate"],["Serial SD curves to monitor recovery","Show reinnervation before voluntary movement in some cases","Low"]],
  evidenceSource:"Electrodiagnosis chapters in Cameron, Physical Agents in Rehabilitation, and Robinson and Snyder-Mackler, Clinical Electrophysiology",
  outcomes:[["Chronaxie","Degree of denervation"],["Shape of curve (kink)","Partial denervation"],["Serial curve shift","Reinnervation over time"]],
  recent:["Nerve conduction studies and needle EMG have largely replaced SD curves for diagnosis, but SD curves remain in Indian BPT syllabi and are used for low-cost follow-up."],
  mnemonic:{word:"R2C", items:[["R","Rheobase: least current with a long pulse"],["2","Double the rheobase"],["C","Chronaxie: pulse duration at that double intensity"]], extra:"Normal chronaxie under 1 ms; denervated often over 10 ms."},
  example:"Three weeks after a mid-shaft humerus fracture, a 35-year-old has wrist drop. An SD curve of the wrist extensors shows a kink at 1 ms, suggesting partial radial nerve denervation. A repeat test at 6 weeks shows the curve moving left.",
  flags:["Testing too early (before 10-14 days) gives falsely normal results","Pacemaker or broken skin at electrode sites","Cold limb or oedema alters thresholds"],
  viva:[["Define chronaxie.","The shortest pulse duration that produces a minimal contraction at twice the rheobase intensity."],["What does a kink in the curve mean?","Partial denervation."],["When should an SD curve be done after nerve injury?","After about 10-14 days, once Wallerian degeneration is complete."]],
  refs:[{b:"cameron",ch:"Electrodiagnostic testing"},{b:"prentice",ch:"Basic principles of electricity and electrical stimulating currents"},{c:"Robinson AJ, Snyder-Mackler L. Clinical Electrophysiology: Electrotherapy and Electrophysiologic Testing. Lippincott Williams and Wilkins.", q:"strength-duration curve chronaxie denervation"}],
  keywords:"strength duration curve rheobase chronaxie electrodiagnosis denervation",
  mcq:[["Chronaxie is the pulse duration at:",["Rheobase","Twice the rheobase","Half the rheobase","Maximum tolerated intensity"],1,"Chronaxie is defined at twice rheobase."],["A kink in the strength-duration curve indicates:",["Normal innervation","Partial denervation","Complete denervation","Myopathy only"],1,"Two populations of fibres (innervated and denervated) give a discontinuity."]]
},
{
  id:"uvr", title:"Ultraviolet radiation therapy (including test dose / erythema grades)", subject:"Electrotherapy", region:"Skin", stages:"steps",
  aliases:["UVR","ultraviolet","Kromayer lamp","Theraktin","Sayer patch test","erythema dose","PUVA","psoriasis"],
  simple:"Ultraviolet rays are invisible rays beyond violet light that cause redness, tanning and peeling of the skin. In physiotherapy they are used for skin problems like psoriasis, acne and infected wounds. A small test dose is given first to find how sensitive the patient's skin is, and later doses are based on it.",
  flow:["Choose source: Kromayer (local) or Theraktin (general)","Sayer patch test finds the minimal erythema dose","Read erythema after 24 hours","Select E1, E2, E3 or E4 for the condition","Calculate time using inverse square law","Progress dose as skin tolerance increases"],
  exam:[
    {h:"Definition and physics", p:["Electromagnetic radiation with wavelengths about 100-400 nm.","UVA 315-400 nm (tanning, used with psoralen in PUVA), UVB 280-315 nm (erythema, vitamin D; narrowband 311 nm for psoriasis), UVC 100-280 nm (bactericidal, used for infected wounds).","Inverse square law: intensity varies inversely with the square of distance; cosine law: rays should strike the skin at right angles."]},
    {h:"Sources", p:["Kromayer lamp: water-cooled mercury vapour lamp, used close or in contact for local treatment.","Theraktin or air-cooled mercury lamps for general (whole body) irradiation.","Fluorescent tubes and PUVA cabinets for psoriasis; narrowband UVB tubes."]},
    {h:"Test dose (Sayer patch test)", p:["Cover the forearm (non-tanned skin) with a card having several apertures; expose all and cover them one by one at set intervals (e.g. 15 s steps) so each window gets a different time.","Protect the rest of the skin and the eyes (goggles for patient and therapist).","Read after 24 hours: the shortest exposure giving just-visible redness is the E1 (minimal erythema dose)."]},
    {h:"Erythema grades", p:["E1 (minimal erythema): latent 6-8 h, faint redness, fades within 24 h, no peeling.","E2 (about 2.5 x E1): latent 4-6 h, clear redness, lasts 2-4 days, slight itch, powdery peeling.","E3 (about 5 x E1): latent about 2 h, intense redness with oedema and heat, lasts about a week, peeling in thin sheets.","E4 (about 10 x E1): blistering, peeling in thick sheets; double E4 used only on infected or sloughy wounds.","Progression with repeated doses: roughly E1 increase 25 percent, E2 increase 50 percent, E3 increase 75 percent to keep the same reaction."]},
    {h:"Indications", p:["Psoriasis (UVB or PUVA), acne vulgaris, vitiligo, infected or sloughy wounds and pressure ulcers (UVC), alopecia (historical), vitamin D deficiency (historical)."]},
    {h:"Dangers and contraindications", p:["Dangers: eye damage (photokeratitis, conjunctivitis), burns from overdose, premature skin ageing, skin cancer with cumulative exposure.","Contraindications: SLE, porphyria, xeroderma pigmentosum, history of skin cancer, acute eczema or dermatitis, photosensitising drugs (tetracyclines, sulphonamides, psoralens unless PUVA is intended), recent radiotherapy, active pulmonary TB, fever."]}
  ],
  tip:"Draw the forearm with the Sayer patch card showing 4-6 windows and exposure times beneath each. Next to it draw a table of E1 to E4 with latent period, appearance, duration and peeling.",
  evidence:[["Narrowband UVB for chronic plaque psoriasis","Effective clearance, widely used","High"],["PUVA for psoriasis","Effective, but more long-term skin cancer risk","High"],["UVC for chronic wounds","Reduces bacterial load; limited evidence for faster healing","Low"]],
  evidenceSource:"Dermatology phototherapy guidelines (British Association of Dermatologists) and Cameron, Physical Agents in Rehabilitation",
  outcomes:[["PASI","Psoriasis severity"],["Wound surface area","Healing of ulcers"],["Erythema grade at 24 hours","Dose response"]],
  recent:["Narrowband UVB (311 nm) has largely replaced broadband UVB for psoriasis and vitiligo, and phototherapy is now mostly delivered in dermatology units.","Targeted 308 nm excimer light is used for small plaques of psoriasis and vitiligo."],
  mnemonic:{word:"ABC", items:[["A","UVA 315-400 nm: Ageing and tAnning, PUVA"],["B","UVB 280-315 nm: Burning (erythema), psoriasis"],["C","UVC 100-280 nm: Can kill bacteria"]], extra:"Always find E1 with a Sayer patch test before treatment."},
  example:"A 40-year-old shopkeeper in Tiruchirappalli with chronic plaque psoriasis on the elbows has a Sayer patch test showing E1 at 30 s. He receives E2 doses to the plaques three times a week with goggles worn.",
  flags:["Eyes must be protected: photokeratitis","Photosensitising drugs or SLE: severe reactions","History of skin cancer or xeroderma pigmentosum","Overdose causing blistering"],
  viva:[["What is E1?","The minimal erythema dose: the shortest exposure producing just-visible redness at 24 hours."],["Which UV band is bactericidal?","UVC (below 280 nm)."],["What is PUVA?","Psoralen taken before UVA exposure, used for psoriasis and vitiligo."]],
  refs:[{b:"cameron",ch:"Ultraviolet radiation"},{b:"prentice",ch:"Ultraviolet therapy"},{c:"British Association of Dermatologists guidance on phototherapy for psoriasis.", q:"narrowband UVB phototherapy psoriasis guideline"}],
  keywords:"ultraviolet radiation UVR erythema E1 E2 E3 E4 Sayer patch test Kromayer psoriasis",
  mcq:[["The latent period of a first degree (E1) erythema is about:",["30 minutes","6-8 hours","48 hours","1 week"],1,"E1 appears after 6-8 hours and fades within a day."],["Which lamp is used for local UVR in contact?",["Theraktin","Kromayer","Infrared luminous lamp","SWD drum"],1,"The water-cooled Kromayer lamp can be used close to or in contact with the skin."]]
},
{
  id:"irr", title:"Infrared radiation", subject:"Electrotherapy", region:"Superficial tissues", stages:"steps",
  aliases:["IRR","infrared lamp","radiant heat","luminous generator","non-luminous generator","superficial heating"],
  simple:"Infrared rays are invisible heat rays just beyond red light. An infrared lamp warms the skin and the tissues just beneath it, easing pain and muscle spasm. It only heats superficially, so it is mainly used before exercise or massage.",
  flow:["Lamp emits infrared rays (770 nm-1 mm)","Rays absorbed in skin and subcutaneous tissue","Local heating causes vasodilation and erythema","Sensory nerve effect reduces pain","Muscle relaxation and reduced spasm","Followed by exercise or massage"],
  exam:[
    {h:"Definition and physics", p:["Electromagnetic radiation of wavelength about 770 nm to 1 mm, between visible light and microwaves.","Near infrared (770-1500 nm) penetrates about 3 mm, into the dermis and subcutaneous tissue; far infrared (1500 nm-15000 nm) is absorbed in the superficial epidermis (about 0.5 mm).","Inverse square law and cosine law govern intensity at the skin."]},
    {h:"Generators", p:["Non-luminous: heated coil or element, emits mainly far infrared, needs about 10-15 minutes to warm up.","Luminous (radiant heat): tungsten or carbon filament bulbs, emit near infrared plus visible light, reach full output almost immediately."]},
    {h:"Physiological effects", p:["Superficial heating, vasodilation and erythema (mottled pigmentation, erythema ab igne, with repeated exposure).","Pain relief by sensory stimulation, muscle relaxation, increased sweating, mild fall in blood pressure if a large area is treated."]},
    {h:"Technique and dosage", p:["Test thermal sensation; uncover and inspect the area; remove creams; patient comfortable.","Lamp at about 50-75 cm, rays perpendicular to the skin; distance adjusted to comfortable warmth.","Time 15-30 minutes (usually 20), daily; check the skin during treatment."]},
    {h:"Indications", p:["Subacute and chronic soft tissue pain, muscle spasm, stiffness before exercise or massage, chronic arthritis, superficial wounds (historically)."]},
    {h:"Dangers and contraindications", p:["Dangers: burns, electric shock, headache, faintness, eye damage (cataract with repeated exposure), chill after treatment, lamp falling.","Contraindications: impaired thermal sensation, impaired circulation, acute inflammation, haemorrhage, malignancy, skin over recent radiotherapy, fever, unreliable patient, defective arterial supply."]}
  ],
  tip:"Draw the lamp at 50-75 cm with rays hitting the skin at 90 degrees, and a cross-section showing near IR reaching subcutaneous tissue and far IR stopping in the epidermis.",
  evidence:[["Superficial heat for acute and subacute low back pain","Small short-term pain relief","Moderate"],["Infrared lamp alone for musculoskeletal pain","Little trial evidence","Low"]],
  evidenceSource:"Cochrane review of superficial heat or cold for low back pain (French et al.) and Cameron, Physical Agents in Rehabilitation",
  outcomes:[["NPRS or VAS","Pain"],["Range of motion","Change after heating and exercise"],["Skin inspection","Safety of dose"]],
  recent:["Near-infrared light-emitting diodes are now used for photobiomodulation at low power, a separate field from heating infrared lamps."],
  mnemonic:{word:"LAMP", items:[["L","Luminous: immediate, near IR, deeper"],["A","At 50-75 cm and 90 degrees"],["M","Minutes: 15-30"],["P","Protect eyes and check skin"]], extra:"Non-luminous needs 10-15 min warm-up."},
  example:"A 50-year-old office worker in Chennai with chronic neck stiffness receives infrared to the upper trapezius for 20 minutes before stretching and posture exercises.",
  flags:["Impaired thermal sensation or circulation: burns","Acute inflammation, haemorrhage or malignancy","Skin damaged by radiotherapy","Eyes: avoid direct exposure"],
  viva:[["Which generator needs warming up?","The non-luminous generator, about 10-15 minutes."],["Which penetrates deeper, near or far infrared?","Near infrared, about 3 mm."],["What is erythema ab igne?","Mottled brown pigmentation from repeated heat exposure."]],
  refs:[{b:"cameron",ch:"Thermal agents: heat"},{b:"prentice",ch:"Infrared modalities"},{c:"French SD, Cameron M, Walker BF, Reggars JW, Esterman AJ. Superficial heat or cold for low back pain. Cochrane Database Syst Rev. 2006;(1):CD004750.", q:"French superficial heat or cold for low back pain Cochrane"}],
  keywords:"infrared radiation IRR luminous non-luminous superficial heat",
  mcq:[["Near infrared penetrates about:",["0.05 mm","3 mm","3 cm","10 cm"],1,"Near IR reaches the dermis and subcutaneous tissue, about 3 mm."],["The usual distance of an infrared lamp from the skin is:",["5-10 cm","50-75 cm","2 m","Contact"],1,"About 50-75 cm, adjusted to comfortable warmth."]]
},
{
  id:"laser", title:"Therapeutic LASER (low-level laser therapy)", subject:"Electrotherapy", region:"Superficial tissues", stages:"steps",
  aliases:["LASER","LLLT","low level laser","cold laser","photobiomodulation","GaAs laser","HeNe laser"],
  simple:"LASER is a narrow beam of light of a single colour with its waves in step. At low power it does not heat but is thought to change cell activity, helping pain and healing. Dose is measured in joules, and eyes must be protected.",
  flow:["Laser diode emits coherent single-wavelength light","Light absorbed by cell chromophores (cytochrome c oxidase)","Changes in ATP and cell signalling","Possible pain relief and anti-inflammatory effect","Dose set in joules per point","Course of several sessions over 2-4 weeks"],
  exam:[
    {h:"Definition", p:["Light Amplification by Stimulated Emission of Radiation. Low-level (low-intensity) lasers below about 500 mW used for non-thermal biological effects."]},
    {h:"Properties and types", p:["Monochromatic (single wavelength), coherent (waves in phase) and collimated (minimal divergence).","Helium-neon (HeNe) 632.8 nm, red, superficial; gallium arsenide (GaAs) 904 nm, infrared, pulsed; gallium aluminium arsenide (GaAlAs) about 780-890 nm.","Most therapy lasers are Class 3B: hazardous to the eye on direct viewing."]},
    {h:"Physiological effects", p:["Photobiomodulation: absorption by mitochondrial chromophores, increased ATP and altered cell signalling.","Claimed effects: pain relief, reduced inflammation, faster wound and tendon healing; responses follow a narrow dose window (too much may inhibit)."]},
    {h:"Dosage and technique", p:["Energy (J) = power (W) x time (s); energy density (J/cm2) = energy / beam area.","Superficial wounds about 1-4 J/cm2; musculoskeletal per-point doses about 2-8 J depending on depth and wavelength (follow WALT recommendations).","Contact technique with light pressure, probe perpendicular, point-by-point grid about 1 cm apart; 2-3 sessions per week.","Goggles specific to the wavelength for patient and therapist; clean probe; sign on the door."]},
    {h:"Indications", p:["Tendinopathy (lateral elbow, Achilles), neck pain, oral mucositis from cancer therapy, slow-healing wounds, trigger points, TMJ pain."]},
    {h:"Contraindications and precautions", p:["Never direct at the eyes; avoid malignancy, the pregnant uterus, thyroid gland, haemorrhage, photosensitive patients or drugs, gonads, recent radiotherapy.","Caution over open epiphyses in children, impaired sensation and tattoos (absorb light and heat)."]}
  ],
  tip:"Draw three beams: ordinary light (many colours, scattered), and laser (one colour, parallel, waves in step), labelling monochromatic, coherent, collimated. Add a probe on a tendon with a 1 cm point grid.",
  evidence:[["LLLT for neck pain","Short-term pain reduction vs placebo","Moderate"],["Photobiomodulation to prevent oral mucositis","Recommended in cancer care guidelines","Moderate-high"],["LLLT for lateral elbow tendinopathy","Benefit only at specific doses; mixed trials","Low-moderate"]],
  evidenceSource:"Chow et al., Lancet 2009 meta-analysis on neck pain, and MASCC/ISOO guidance on photobiomodulation for oral mucositis (Zadik et al., 2019)",
  outcomes:[["NPRS or VAS","Pain"],["Neck Disability Index","Neck function"],["Wound area","Healing"]],
  recent:["The term photobiomodulation therapy has replaced LLLT in much of the literature.","MASCC/ISOO guidelines (Zadik et al., Support Care Cancer 2019) recommend photobiomodulation to prevent oral mucositis in some cancer treatments."],
  mnemonic:{word:"MCC", items:[["M","Monochromatic"],["C","Coherent"],["C","Collimated"]], extra:"Dose in joules: power x time. Eyes always protected."},
  example:"A 38-year-old software engineer in Bengaluru with chronic neck pain receives GaAlAs laser to tender points (about 4 J per point) twice weekly for 3 weeks alongside neck exercises.",
  flags:["Direct or reflected beam into the eye","Over known or suspected malignancy","Over the pregnant uterus or thyroid","Photosensitising drugs"],
  viva:[["What are the three properties of laser light?","Monochromatic, coherent and collimated."],["How is laser dose calculated?","Energy (J) = power (W) x time (s); divide by area for J/cm2."],["What class are most therapeutic lasers?","Class 3B."]],
  refs:[{b:"cameron",ch:"Lasers and light"},{b:"prentice",ch:"Low-level laser therapy"},{c:"Chow RT, Johnson MI, Lopes-Martins RA, Bjordal JM. Efficacy of low-level laser therapy in the management of neck pain: a systematic review and meta-analysis. Lancet. 2009;374:1897-1908.", q:"Chow low-level laser therapy neck pain meta-analysis Lancet 2009"},{c:"Zadik Y, et al. Systematic review of photobiomodulation for the management of oral mucositis in cancer patients and clinical practice guidelines. Support Care Cancer. 2019;27:3969-3983.", q:"Zadik photobiomodulation oral mucositis guidelines 2019"}],
  keywords:"laser LLLT photobiomodulation monochromatic coherent collimated",
  mcq:[["The wavelength of a helium-neon laser is:",["904 nm","632.8 nm","311 nm","27.12 MHz"],1,"HeNe emits red light at 632.8 nm."],["Laser dose in joules equals:",["Power x time","Voltage x current","Frequency x wavelength","Intensity / area"],0,"Energy (J) = power (W) x time (s)."]]
},
{
  id:"iontophoresis", title:"Iontophoresis", subject:"Electrotherapy", region:"Skin and superficial tissues", stages:"steps",
  aliases:["iontophoresis","ion transfer","dexamethasone iontophoresis","tap water iontophoresis","hyperhidrosis","drug delivery"],
  simple:"Iontophoresis uses a small direct current to push charged drug particles through the skin. A drug with a negative charge is placed under the negative electrode so it is repelled into the tissue. It is used for local inflammation, excessive sweating and some skin conditions.",
  flow:["Choose drug and identify its charge","Place drug under electrode of same polarity","Apply direct current (1-4 mA)","Like charges repel ions into skin","Dose expressed in mA-minutes","Check skin for burns after treatment"],
  exam:[
    {h:"Definition and principle", p:["Introduction of ions of a drug into the tissues using a direct (galvanic) current.","Like charges repel: negatively charged drug ions are driven from the cathode (negative), positive ions from the anode (positive).","Main route is through sweat ducts and hair follicles; penetration is shallow (a few millimetres), with later spread by circulation."]},
    {h:"Common ions", p:["Dexamethasone sodium phosphate (negative): local inflammation such as tendinopathy, plantar fasciitis.","Lidocaine (positive): local anaesthesia.","Acetic acid (negative): calcific deposits (weak evidence).","Hyaluronidase (positive): oedema; tap water (both poles alternated): hyperhidrosis of hands and feet; iodine or salicylate (negative): scar tissue, pain."]},
    {h:"Dosage and parameters", p:["Continuous direct current about 1-4 mA; dose in mA-minutes, typically 40-80 mA-min (e.g. 4 mA for 10-20 min).","Current density limit: about 0.5 mA/cm2 under the cathode and 1.0 mA/cm2 under the anode; the cathode is usually made larger because alkaline burns under it are more serious.","Dispersive electrode larger than the active one, a few centimetres away; buffered electrodes reduce pH changes.","Tap water for hyperhidrosis: about 15-20 mA (as tolerated) for 20-30 min, several times a week initially."]},
    {h:"Procedure", p:["Check sensation and skin; clean skin (no shaving immediately before).","Soak the active pad with drug, connect correct polarity, increase current slowly, check skin every few minutes.","Inspect skin after treatment; explain mild redness is normal."]},
    {h:"Dangers and contraindications", p:["Chemical (acid or alkaline) burns, drug allergy or sensitivity, electric shock.","Contraindications: known allergy to the drug (e.g. aspirin for salicylates, iodine sensitivity), broken skin, impaired sensation, pacemaker, metal near the surface, pregnancy (for systemic drugs), malignancy in the area."]},
    {h:"Conclusion", p:["Iontophoresis offers local, needle-free drug delivery; tap water iontophoresis for hyperhidrosis is well supported, while evidence for steroid and acetic acid iontophoresis is limited."]}
  ],
  tip:"Draw a forearm with the active (cathode, negative) electrode holding dexamethasone minus ions and arrows driving them into the skin, the anode a few centimetres away, and write dose = mA x min = 40 mA-min.",
  evidence:[["Tap water iontophoresis for palmar and plantar hyperhidrosis","Reduces sweating","Moderate"],["Dexamethasone iontophoresis for plantar fasciitis","Short-term pain relief","Low-moderate"],["Acetic acid iontophoresis for calcific deposits","No clear advantage over exercise","Low"]],
  evidenceSource:"Cameron, Physical Agents in Rehabilitation, and dermatology guidance on hyperhidrosis management",
  outcomes:[["NPRS or VAS","Pain"],["Gravimetric sweat measurement or HDSS","Hyperhidrosis severity"],["Foot Function Index","Plantar heel pain function"]],
  recent:["Buffered pre-filled electrode patches and low-current wearable iontophoresis patches allow longer, lower-intensity sessions with fewer burns."],
  mnemonic:{word:"LIKE", items:[["L","Like charges repel"],["I","Ion polarity decides the electrode"],["K","Keep cathode larger: alkaline burn risk"],["E","Estimate dose in mA-minutes"]], extra:"Dexamethasone is negative: use cathode."},
  example:"A 42-year-old teacher in Salem with plantar heel pain receives dexamethasone iontophoresis at 4 mA for 10 minutes (40 mA-min) on the cathode, combined with calf and plantar fascia stretching.",
  flags:["Drug allergy (aspirin, iodine, lidocaine)","Chemical burns, especially under the cathode","Broken skin or loss of sensation","Pacemaker or metal near the surface"],
  viva:[["Which electrode is used for dexamethasone?","The cathode (negative), because dexamethasone sodium phosphate is negatively charged."],["What is the unit of iontophoresis dose?","mA-minutes (current x time)."],["Why is the cathode larger?","Alkaline reactions under the cathode cause more serious burns, so current density is kept lower."]],
  refs:[{b:"cameron",ch:"Iontophoresis"},{b:"prentice",ch:"Iontophoresis"}],
  keywords:"iontophoresis dexamethasone polarity mA-min hyperhidrosis",
  mcq:[["Dexamethasone sodium phosphate is delivered from the:",["Anode","Cathode","Either electrode","Dispersive pad only"],1,"It is negatively charged, so it is repelled from the cathode."],["A typical iontophoresis dose is:",["4 J/cm2","40 mA-min","27 MHz","E2"],1,"Dose is current multiplied by time, often 40-80 mA-min."]]
},
{
  id:"cryotherapy", title:"Cryotherapy and contrast bath", subject:"Electrotherapy", region:"Soft tissues", stages:"steps",
  aliases:["cryotherapy","ice pack","ice massage","cold therapy","contrast bath","hunting reaction","RICE"],
  simple:"Cryotherapy means treating with cold, such as ice packs or ice massage, to reduce pain, swelling and muscle spasm. A contrast bath alternates warm and cold water to pump fluid out of a swollen hand or foot. Both are simple, but cold can damage nerves and skin if used too long.",
  flow:["Cold applied: ice pack, massage, immersion or spray","Skin and tissue temperature fall","Vasoconstriction, slower metabolism and nerve conduction","Sensation: cold, burning, aching, then numbness","Pain and spasm reduced, exercise possible","Contrast bath alternates hot and cold for oedema"],
  exam:[
    {h:"Definition", p:["The therapeutic use of cold to lower tissue temperature for pain relief, reduced spasm and control of acute inflammation."]},
    {h:"Methods and dosage", p:["Ice pack: crushed ice in a damp towel, 10-20 minutes, repeated every 2-3 hours in acute injury.","Ice massage: ice cup rubbed over a small area for 5-10 minutes until numb.","Cold immersion: 10-15 degrees C water for 10-20 minutes; ice towels, cold compression units and vapocoolant spray (spray and stretch).","Sensation sequence: cold, burning, aching, numbness (CBAN); stop at numbness."]},
    {h:"Physiological effects", p:["Vasoconstriction, then possible cold-induced vasodilation (Lewis hunting reaction) with long or very cold exposure.","Reduced nerve conduction velocity and muscle spindle activity (less pain and spasm), reduced metabolic rate and secondary hypoxic injury.","Effect on swelling is mainly via compression and elevation; recent views suggest ice may delay parts of healing, so use is short and targeted."]},
    {h:"Contrast bath", p:["Two baths: hot 38-44 degrees C and cold 10-15 degrees C.","Common regime: 3-4 minutes hot then 1 minute cold, repeated 4-5 times (about 20-30 minutes), ending in hot for stiffness or cold for swelling.","Indications: subacute oedema of hand or foot, CRPS (sympathetic stimulation), stiffness after fracture immobilisation; evidence is weak."]},
    {h:"Indications", p:["Acute soft tissue injury (with compression and elevation), post-operative pain, muscle spasm, spasticity (short-term), burns first aid with cool water, acute bursitis, delayed onset muscle soreness."]},
    {h:"Contraindications and dangers", p:["Cold hypersensitivity (cold urticaria), cryoglobulinaemia, paroxysmal cold haemoglobinuria, Raynaud's phenomenon, peripheral vascular disease, impaired sensation.","Dangers: ice burn (frostbite), nerve palsy over superficial nerves (common peroneal at the fibular neck, ulnar at the elbow), cold-induced hypertension in cardiac patients."]}
  ],
  tip:"Draw an ankle with an ice pack wrapped in a towel and label time 10-20 min. Alongside, draw two buckets labelled hot 38-44 degrees C (4 min) and cold 10-15 degrees C (1 min) with arrows showing 4-5 cycles.",
  evidence:[["Ice with exercise after ankle sprain","Short-term pain relief; little effect on swelling alone","Low-moderate"],["Cryotherapy after knee arthroplasty","Small pain reduction, little functional effect","Low"],["Contrast bath for oedema","Inconsistent results","Very low"]],
  evidenceSource:"Bleakley et al., Am J Sports Med 2004 systematic review, and Dubois and Esculier, Br J Sports Med 2020 (PEACE and LOVE)",
  outcomes:[["NPRS","Pain"],["Figure-of-eight ankle measure or volumetry","Swelling"],["Range of motion","Function after cooling"]],
  recent:["The PEACE and LOVE framework (Dubois and Esculier, BJSM 2020) questions routine icing of acute soft tissue injury, emphasising protection, compression, education and early loading."],
  mnemonic:{word:"CBAN", items:[["C","Cold"],["B","Burning"],["A","Aching"],["N","Numbness: stop here"]], extra:"Contrast bath: hot 4 min, cold 1 min, 4-5 cycles."},
  example:"A 22-year-old kabaddi player in Madurai sprains his ankle. He uses a crushed ice pack in a wet towel for 15 minutes every 2-3 hours with compression and elevation, and starts gentle weight-bearing within 2 days.",
  flags:["Cold urticaria, cryoglobulinaemia or Raynaud's","Superficial nerves (common peroneal, ulnar): nerve palsy","Impaired sensation or circulation: ice burn","Ice directly on skin for long periods"],
  viva:[["What is the hunting reaction?","Alternating vasoconstriction and vasodilation in tissue exposed to intense cold (Lewis reaction)."],["What is the ratio of hot to cold in a contrast bath?","About 3-4:1 (e.g. 4 minutes hot, 1 minute cold)."],["Why is ice dangerous over the fibular neck?","The common peroneal nerve is superficial there and can develop cold-induced palsy."]],
  refs:[{b:"cameron",ch:"Thermal agents: cold"},{b:"prentice",ch:"Cryotherapy and thermotherapy"},{c:"Bleakley C, McDonough S, MacAuley D. The use of ice in the treatment of acute soft-tissue injury: a systematic review of randomized controlled trials. Am J Sports Med. 2004;32:251-261.", q:"Bleakley ice acute soft-tissue injury systematic review 2004"},{c:"Dubois B, Esculier JF. Soft-tissue injuries simply need PEACE and LOVE. Br J Sports Med. 2020;54:72-73.", q:"Dubois Esculier PEACE and LOVE soft tissue injuries"}],
  keywords:"cryotherapy ice pack ice massage contrast bath hunting reaction",
  mcq:[["The correct sequence of sensations during ice application is:",["Numbness, aching, burning, cold","Cold, burning, aching, numbness","Aching, cold, numbness, burning","Burning, cold, numbness, aching"],1,"CBAN: stop at numbness."],["Which is a contraindication to cryotherapy?",["Acute ankle sprain","Raynaud's phenomenon","Muscle spasm","DOMS"],1,"Cold triggers vasospasm in Raynaud's phenomenon."]]
},
{
  id:"wax-bath", title:"Paraffin wax bath therapy", subject:"Electrotherapy", region:"Hand and foot", stages:"steps",
  aliases:["wax bath","paraffin wax","wax therapy","dip and wrap","rheumatoid hand","superficial heat"],
  simple:"A wax bath is a tank of melted paraffin wax mixed with a little mineral oil. The hand or foot is dipped several times so a coat of warm wax forms, giving even, gentle heat to small joints. It eases stiffness and pain before exercise, especially in arthritis of the hands.",
  flow:["Wax and mineral oil melted in thermostatic bath","Hand washed, checked and dipped repeatedly","Layers of wax form an insulating glove","Wax releases latent heat as it solidifies","Joints warm, stiffness and pain reduce","Wax peeled off, followed by exercises"],
  exam:[
    {h:"Definition and physics", p:["Superficial heat by conduction using molten paraffin wax mixed with mineral (liquid paraffin) oil, about 7 parts wax to 1 part oil.","Pure paraffin melts at about 52-54 degrees C; the oil lowers the melting point so the mixture can be used at about 42-50 degrees C.","Low specific heat and low thermal conductivity mean skin tolerates higher temperatures than water; latent heat is released as the wax solidifies, and the coating traps heat."]},
    {h:"Methods", p:["Dip and wrap: dip 6-12 times, letting each layer set; wrap in plastic and towel for 15-20 minutes (most common).","Dip and immerse (dip and leave in): after initial layers keep the part in the bath for 15-20 minutes; hotter, so used with care.","Painting (brushing) layers on areas that cannot be dipped, such as the knee, elbow or back; pack or bandage method."]},
    {h:"Physiological effects", p:["Superficial heating of skin and small joints, vasodilation and sweating that softens the skin.","Reduced pain and stiffness, increased extensibility of collagen before stretching and exercise, softening of scars and dry skin."]},
    {h:"Indications", p:["Rheumatoid arthritis of hand (non-acute) and hand osteoarthritis, stiffness after fracture (Colles fracture), scleroderma hands, contractures, scar tissue."]},
    {h:"Procedure and precautions", p:["Check thermal sensation and skin; remove jewellery; wash and dry the part.","Check wax temperature with a thermometer; patient keeps fingers apart and still in the bath and does not touch the sides or bottom.","Follow immediately with exercises; return clean wax to the bath; keep the bath covered and clean it regularly."]},
    {h:"Contraindications and dangers", p:["Open wounds, skin infection or rash, impaired sensation or circulation, acute inflammation or acute flare, allergy to wax, malignancy in the area.","Dangers: burns (overheated wax or moving the part), cross-infection, fire risk if the bath is overheated."]}
  ],
  tip:"Draw a thermostatic wax bath with a hand dipping in, label wax:oil 7:1, temperature 42-50 degrees C, 6-12 dips, wrap in plastic and towel for 15-20 minutes, then exercise.",
  evidence:[["Paraffin wax combined with exercise for rheumatoid hands","Short-term improvement in stiffness and grip","Low-moderate"],["Thermal agents for hand OA","Conditionally recommended as adjunct","Low"]],
  evidenceSource:"Cochrane review of thermotherapy for rheumatoid arthritis (Robinson et al.) and ACR 2019 osteoarthritis guideline (Kolasinski et al.)",
  outcomes:[["Grip strength","Hand function"],["Morning stiffness duration","Inflammatory arthritis activity"],["AUSCAN or DASH","Hand function"]],
  recent:["The 2019 ACR/Arthritis Foundation osteoarthritis guideline (Kolasinski et al.) conditionally recommends thermal interventions, used alongside exercise."],
  mnemonic:{word:"DIP", items:[["D","Dip 6-12 times, fingers apart"],["I","Insulate with plastic and towel 15-20 min"],["P","Peel off and exercise at once"]], extra:"Wax:oil about 7:1, used at 42-50 degrees C."},
  example:"A 52-year-old woman in Vellore with rheumatoid arthritis in remission has morning stiffness in the fingers. She has dip-and-wrap wax for 15 minutes followed by tendon gliding and grip exercises.",
  flags:["Open wounds or skin infection","Impaired thermal sensation or circulation: burns","Acute inflammatory flare","Overheated wax: check with thermometer"],
  viva:[["Why is mineral oil added to wax?","To lower the melting point so it can be used at a comfortable temperature."],["Why can patients tolerate wax at about 50 degrees C?","Wax has low specific heat and low thermal conductivity, and the first layer insulates the skin."],["What is the most common method?","Dip and wrap."]],
  refs:[{b:"cameron",ch:"Thermal agents: heat"},{b:"prentice",ch:"Cryotherapy and thermotherapy"},{c:"Robinson V, et al. Thermotherapy for treating rheumatoid arthritis. Cochrane Database Syst Rev. 2002;(2):CD002826.", q:"thermotherapy rheumatoid arthritis Cochrane paraffin"},{c:"Kolasinski SL, et al. 2019 American College of Rheumatology/Arthritis Foundation guideline for the management of osteoarthritis of the hand, hip, and knee. Arthritis Care Res. 2020;72:149-162.", q:"Kolasinski 2019 ACR guideline osteoarthritis hand hip knee"}],
  keywords:"paraffin wax bath dip and wrap rheumatoid hand superficial heat",
  mcq:[["The usual wax to mineral oil ratio in a wax bath is:",["1:1","7:1","1:7","20:1"],1,"About 7 parts wax to 1 part oil lowers the melting point."],["Which is a contraindication to wax bath?",["Chronic stiff hand after Colles fracture","Open wound on the hand","Hand OA","Scar tissue"],1,"Open wounds risk infection and contamination of the bath."]]
}
]);
